    @Test void secondSourceFailureRollsBackEmployeeAndFirstSource()throws Exception{var f=data();grant(f,f.department());grant(f,f.other());String last=jdbc.queryForObject("SELECT id FROM authorization_source WHERE employee_id=? ORDER BY id DESC LIMIT 1",String.class,f.employee());var in=stateInput(0,"INACTIVE");String p=checkedPreview(previewState(f,in));db.execute("CREATE TRIGGER be27_second_source BEFORE UPDATE ON authorization_source FOR EACH ROW BEGIN IF NEW.id='"+last+"' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='fixture second source'; END IF; END");try{assertThat(saveState(f,in,p,id()).statusCode()).isEqualTo(500);}finally{db.execute("DROP TRIGGER be27_second_source");}assertThat(jdbc.queryForObject("SELECT status FROM employee WHERE id=?",String.class,f.employee())).isEqualTo("ACTIVE");assertThat(count("SELECT SUM(source_epoch) FROM authorization_source WHERE employee_id=?",f.employee())).isZero();assertThat(count("SELECT COUNT(*) FROM role_grant g JOIN grant_baseline b ON b.id=g.baseline_id JOIN authorization_source s ON s.id=b.source_id WHERE s.employee_id=? AND g.status='ACTIVE'",f.employee())).isEqualTo(2);}


