    @Test void internalEmployeePortFailureCannotBeCaughtToCommitPartialBatch()throws Exception{var f=data();grant(f,f.department());db.execute("CREATE TRIGGER be27_caught_failure BEFORE INSERT ON audit_event FOR EACH ROW BEGIN IF NEW.event_type='EMPLOYEE_STATE_CHANGED' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='fixture caught failure'; END IF; END");try{var jwt=app.getBean(IdentityTokens.class).verify(token,IdentityTokens.Family.ADMIN);assertThatThrownBy(()->app.getBean(CommandBoundary.class).execute(()->app.getBean(ManagementAccess.class).global(jwt).identity(),c->{try{app.getBean(com.adgn.backend.lifecycle.EmployeeStateWriter.class).apply(c,f.employee(),new com.adgn.backend.lifecycle.LifecycleInput.EmployeeState(0L,"INACTIVE","Fixture caught failure"),id());}catch(RuntimeException ignored){}return true;})).isInstanceOf(RuntimeException.class);}finally{db.execute("DROP TRIGGER be27_caught_failure");}assertThat(jdbc.queryForObject("SELECT status FROM employee WHERE id=?",String.class,f.employee())).isEqualTo("ACTIVE");assertThat(count("SELECT source_epoch FROM authorization_source WHERE employee_id=?",f.employee())).isZero();}
