    @Test void businessQueryRemainsDeniedAfterEmployeeRestoration()throws Exception{
        var f=data();grant(f,f.department());String permission=id(),service=id();jdbc.update("INSERT INTO permission(id,system_id,code,name,permission_type,created_at) VALUES(?,?,'entry','Fixture entry','SYSTEM_ACCESS',UTC_TIMESTAMP(6))",permission,f.system());jdbc.update("INSERT INTO role_permission(role_id,permission_id,system_id) VALUES(?,?,?)",f.role(),permission,f.system());jdbc.update("INSERT INTO service_identity(id,subject,kind,system_id) VALUES(?,?,'BUSINESS',?)",service,service,f.system());
        var now=java.time.Instant.now();var claims=new com.nimbusds.jwt.JWTClaimsSet.Builder().issuer("urn:rbac:business").audience("rbac-business").subject(service).jwtID(id()).issueTime(Date.from(now)).expirationTime(Date.from(now.plusSeconds(300))).claim("systemId",f.system()).build();var jwt=new com.nimbusds.jwt.SignedJWT(new com.nimbusds.jose.JWSHeader.Builder(com.nimbusds.jose.JWSAlgorithm.RS256).keyID("business").build(),claims);jwt.sign(new com.nimbusds.jose.crypto.RSASSASigner(businessKey));String bearer=jwt.serialize();
        var query=Map.of("employeeKey",f.employee(),"companyId",f.company());var before=call("/api/v1/integration/authorization-queries",query,bearer,null,Map.of());assertThat(before.statusCode()).as(before.body()).isEqualTo(200);assertThat(body(before).path("canAccessSystem").booleanValue()).isTrue();
        var in=stateInput(0,"INACTIVE");assertThat(saveState(f,in,checkedPreview(previewState(f,in)),id()).statusCode()).isEqualTo(200);var denied=call("/api/v1/integration/authorization-queries",query,bearer,null,Map.of());assertThat(denied.statusCode()).isEqualTo(200);assertThat(body(denied).path("canAccessSystem").booleanValue()).isFalse();
        in=stateInput(1,"ACTIVE");assertThat(saveState(f,in,checkedPreview(previewState(f,in)),id()).statusCode()).isEqualTo(200);var restored=call("/api/v1/integration/authorization-queries",query,bearer,null,Map.of());assertThat(restored.statusCode()).isEqualTo(200);assertThat(body(restored).path("canAccessSystem").booleanValue()).isFalse();
    }
